def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])

    # Count all cells to find the most frequent (background)
    all_counts = Counter()
    for row in grid:
        all_counts.update(row)
    global_bg = max(all_counts, key=all_counts.get)

    result = []
    for i in range(h // 2):
        row_out = []
        for j in range(w // 2):
            # 2x2 block
            block = [
                grid[i][j], grid[i][j+1],
                grid[i+1][j], grid[i+1][j+1]
            ]
            block_counts = Counter(block)

            # Determine output based on block composition
            if len(set(block)) == 1:
                # All same color in block
                row_out.append(5)
            elif block_counts[global_bg] >= 2:
                # Mostly background - output most frequent non-background
                non_bg = {c: cnt for c, cnt in block_counts.items() if c != global_bg}
                if non_bg:
                    row_out.append(max(non_bg, key=non_bg.get))
                else:
                    row_out.append(5)
            else:
                # Not much background - output the minority color
                min_count = min(block_counts.values())
                rares = [c for c, cnt in block_counts.items() if cnt == min_count]
                non_bg_rares = [c for c in rares if c != global_bg]
                if non_bg_rares:
                    row_out.append(non_bg_rares[0])
                else:
                    row_out.append(5)
        result.append(row_out)

    return result
